{"cards": [{"node_code": "N_5db4e2a3ac0d64a8", "definition": "研究流体动压与静压润滑理论，涵盖流体膜建立机制、压力分布计算、承载能力分析及典型轴承/滑动面设计。", "boundary": "聚焦于完全流体润滑状态，即摩擦副表面被连续流体膜完全分离。包括雷诺方程求解、油膜厚度与压力场分布、稳定性分析及动压/静压轴承设计。不涉及表面直接接触、弹流效应或润滑剂化学改性。", "includes": ["流体动压润滑理论、雷诺方程及数值解法", "流体静压润滑系统原理、节流器设计与控制", "滑动轴承、导轨等流体润滑元件的设计与性能分析"], "excludes": ["涉及表面微凸体接触或膜破裂的混合/边界润滑（归入弹流、混合与边界润滑）", "润滑剂本身的流变特性、添加剂化学或固体润滑材料（归入润滑油脂、添加剂与固体润滑）"], "sibling_distinctions": [{"other_code": "N_d4550071c62cf3b3", "rule": "本节点关注完全流体膜分离状态，兄弟节点关注膜破裂、表面接触或高载荷下的弹流效应；涉及纯流体动力学归本节点，涉及接触力学或混合状态归兄弟节点。"}, {"other_code": "N_9da401ea1bc6f510", "rule": "本节点关注流体膜动力学与系统设计，兄弟节点关注润滑介质本身的物理化学性质；涉及油膜压力分布归本节点，涉及润滑油粘度、添加剂配方归兄弟节点。"}], "cross_boundary_rule": "涉及流体润滑设计时，若侧重流体膜动力学方程与压力场归本节点；若侧重润滑剂选型或添加剂对膜的影响归兄弟节点N_9da401ea1bc6f510。"}, {"node_code": "N_d4550071c62cf3b3", "definition": "研究弹流润滑、混合润滑及边界润滑理论，涵盖高载荷下流体膜变形、表面微凸体接触及润滑膜破裂机制。", "boundary": "聚焦于非完全流体润滑状态，包括点/线接触下的弹流润滑（EHL）、流体膜部分破裂的混合润滑及表面直接接触的边界润滑。涉及接触力学、表面粗糙度影响及润滑膜破裂临界条件。", "includes": ["弹流润滑理论、接触应力与膜厚关系", "混合润滑状态下的流体-固体接触模型", "边界润滑机理、摩擦系数及表面相互作用"], "excludes": ["完全流体润滑状态下的纯流体动力学分析（归入流体动压与静压润滑）", "润滑剂基础理化性质或添加剂化学（归入润滑油脂、添加剂与固体润滑）"], "sibling_distinctions": [{"other_code": "N_5db4e2a3ac0d64a8", "rule": "本节点关注膜破裂或表面接触状态，兄弟节点关注完全流体膜分离；涉及接触力学或混合状态归本节点，涉及纯流体压力场归兄弟节点。"}, {"other_code": "N_9da401ea1bc6f510", "rule": "本节点关注润滑状态下的界面行为，兄弟节点关注润滑介质属性；涉及膜破裂机制归本节点，涉及润滑剂配方归兄弟节点。"}], "cross_boundary_rule": "涉及润滑状态判定时，若侧重流体膜完全建立归兄弟节点N_5db4e2a3ac0d64a8；若侧重膜破裂、接触或混合状态归本节点。"}, {"node_code": "N_9da401ea1bc6f510", "definition": "研究润滑油、润滑脂、固体润滑剂的性能、配方、添加剂作用机理及固体润滑材料特性。", "boundary": "聚焦于润滑介质本身的物理化学性质、流变学行为、添加剂化学及固体润滑材料。包括基础油选择、极压/抗磨添加剂、润滑脂结构及固体润滑剂（如石墨、MoS2）应用。", "includes": ["润滑油、润滑脂的理化性能、流变学及配方设计", "润滑添加剂（极压、抗磨、抗氧化等）作用机理", "固体润滑材料特性、应用及表面改性"], "excludes": ["流体膜动力学方程求解或轴承设计（归入流体动压与静压润滑）", "润滑状态下的接触力学或膜破裂机制（归入弹流、混合与边界润滑）"], "sibling_distinctions": [{"other_code": "N_5db4e2a3ac0d64a8", "rule": "本节点关注润滑介质属性，兄弟节点关注流体膜动力学；涉及润滑油粘度、添加剂归本节点，涉及油膜压力分布归兄弟节点。"}, {"other_code": "N_d4550071c62cf3b3", "rule": "本节点关注润滑介质对界面行为的影响，